cd src/Api/Api.Tests && cat > PayByCardSteps.cs <<'E'
using Reqnroll;
using Xunit;

namespace Api.Tests;

[Binding]
public class PayByCardSteps
{
    private bool _validCard;
    private int _accepted;

    [Given("a returning customer with a valid card")]
    public void GivenAReturningCustomerWithAValidCard() => _validCard = true;

    [When("a basket of {int} cents is paid")]
    public void WhenABasketIsPaid(int cents) => _accepted = _validCard ? cents : 0;

    [Then("the payment is accepted for {int} cents")]
    public void ThenThePaymentIsAcceptedFor(int cents) => Assert.Equal(cents, _accepted);
}
E
sed -i 's#</Project>#  <ItemGroup>\n    <ReqnrollFeatureFiles Include="..\\..\\..\\docs\\features\\**\\*.feature" Link="Features\\%(RecursiveDir)%(Filename)%(Extension)" />\n  </ItemGroup>\n</Project>#' Api.Tests.csproj
cd .. && dotnet build Api.slnx --nologo 2>&1 | tail -5; dotnet test Api.slnx --nologo --no-build 2>&1 | tail -5

